// 'items' é uma variável especial no nó Code
// que contém todos os itens recebidos.

const todosOsTitulos = [];

for (const item of items) {
  // Para cada 'item' na lista, pegamos o JSON dele
  const titulo = item.json.info.Title;

  // Adicionamos o título extraído a uma nova lista
  todosOsTitulos.push({
    titulo_do_pdf: titulo
  });
}
$input.first().json.text
// O nó de código retorna o que você colocar aqui.
// Estamos retornando a lista que acabamos de criar.
return todosOsTitulos;

// Acessa os itens que chegam como input para este nó
const items = $input.all();

let previousData = [];

// Tenta pegar os dados da iteração anterior.
// Isso vai FALHAR na primeira iteração, e é exatamente o que queremos.
try {
  previousData = $items("Json Final")[0].json.allData;
} catch (error) {
  // Se o bloco 'try' falhar, significa que é a primeira iteração.
  // O 'catch' captura o erro e nós simplesmente definimos 'previousData'
  // como um array vazio, sem travar o workflow.
  previousData = [];
}
// Pega o título e o nome do arquivo da iteração ATUAL
const newTitle = $items("AI Agent1")[0].json.output.title; 
const newFileName = $('Edit Fields').first().json.fileName;
const newDepartamento = $items("AI Agent2")[0].json.output.departamento; 
const newKeywords = $items("AI Agent2")[0].json.output.keywords;
const newAno = $items("AI Agent2")[0].json.output.ano; 

// Adiciona os novos dados ao array (que estará vazio na 1ª iteração
// ou conterá os dados anteriores nas iterações seguintes)
const newData = {
  "filename": newFileName,
  "title": newTitle,
  "departamento": newDepartamento,
  "keywords": newKeywords,
  "ano": newAno
};
previousData.push(newData);

// Retorna o array completo para a próxima iteração
return {
  allData: previousData
};

